import '../../data/api_client.dart';import '../../data/api_models.dart';import 'governance_models.dart';import 'governance_repository.dart';
abstract interface class AuditExporter {Future<void> export(String format);}
class ApiGovernanceRepository implements GovernanceRepository {const ApiGovernanceRepository(this.api,{required this.auditExporter});final AnumApiClient api;final AuditExporter auditExporter;Future<List<JsonMap>> _list(String p)async{final v=await api.request('GET',p);return ((v['data'] as List<Object?>?)??const[]).cast<JsonMap>();}@override Future<GovernanceSnapshot> load()async{try{final v=await Future.wait([api.request('GET','/api/v1/organization/governance'),_list('/api/v1/policy-packs'),_list('/api/v1/marketplace/packages'),_list('/api/v1/marketplace/installs'),_list('/api/v1/routing/targets'),api.request('GET','/api/v1/enterprise/operations')]);final installs=v[3] as List<JsonMap>;return GovernanceSnapshot(summary:_summary(v[0] as JsonMap),policies:(v[1] as List<JsonMap>).map(_policy).toList(),marketplace:(v[2] as List<JsonMap>).map((x)=>_market(x,installs)).toList(),targets:(v[4] as List<JsonMap>).map(_target).toList(),operations:_ops(v[5] as JsonMap));}on ApiException catch(e){if(e.statusCode==0||e.statusCode>=500)throw GovernanceOfflineException(e.message);rethrow;}}@override Future<PolicyPack> createBaselinePolicy(String name)async=>_policy(await api.request('POST','/api/v1/policy-packs',body:{'name':name,'description':'Mobile-managed organization baseline','rules':[{'action':'integration.write','effect':'require_approval','conditions':{'risk':'high'}}]}));@override Future<PolicyPack> setPolicyActive(String id,{required bool active})async=>_policy(await api.request('POST','/api/v1/policy-packs/$id/${active?'activate':'archive'}'));@override Future<void> createRoleTemplate(String name,List<String> permissions)async{await api.request('POST','/api/v1/role-templates',body:{'name':name,'permissions':permissions});}@override Future<void> createApprovalRule(String name,String pattern,{int minimumApprovers=1,List<String> requiredRoles=const['owner']})async{await api.request('POST','/api/v1/organization/approval-rules',body:{'name':name,'action_pattern':pattern,'minimum_approvers':minimumApprovers,'required_roles':requiredRoles});}@override Future<void> updateMemoryGovernance({required int retentionDays,required bool allowPermanent,required bool requireProvenance,List<String> sourceTypes=const[]})async{await api.request('PUT','/api/v1/organization/memory-governance',body:{'default_retention_days':retentionDays,'allow_permanent_retention':allowPermanent,'require_provenance':requireProvenance,'allowed_source_types':sourceTypes});}@override Future<void> upsertMarketplacePackage(MarketplaceItem item)async{await api.request('PUT','/api/v1/marketplace/packages/${item.id}',body:{'id':item.id,'name':item.name,'kind':item.kind,'version':item.version,'publisher':item.publisher,'verified':item.verified,'permissions':item.permissions,'regions':item.regions});}@override Future<void> deleteMarketplacePackage(String id)async{await api.request('DELETE','/api/v1/marketplace/packages/$id');}@override Future<void> installPackage(String id)async{await api.request('POST','/api/v1/marketplace/packages/$id/install',body:<String,Object?>{});}@override Future<void> uninstallPackage(String id)async{await api.request('DELETE','/api/v1/marketplace/packages/$id/install');}@override Future<RoutingTarget> updateTarget(RoutingTarget t)async=>_target(await api.request('PUT','/api/v1/routing/targets/${t.id}',body:{'id':t.id,'region':t.region,'provider':t.provider,'model':t.model,'status':t.status,'modalities':t.modalities,'sensitivity':t.sensitivity,'cost_per_1k_tokens':t.cost,'latency_ms':t.latencyMs}));@override Future<void> exportAudit(String format)=>auditExporter.export(format);
GovernanceSummary _summary(JsonMap j)=>GovernanceSummary(policyPacks:(j['policy_packs'] as num).toInt(),activePolicyPacks:(j['active_policy_packs'] as num).toInt(),roleTemplates:(j['role_templates'] as num).toInt(),approvalRules:(j['approval_rules'] as num).toInt());PolicyPack _policy(JsonMap j)=>PolicyPack(id:j['id']! as String,name:j['name']! as String,version:(j['version'] as num).toInt(),active:j['active']! as bool,rules:((j['rules'] as List<Object?>?)??const[]).cast<JsonMap>().map((x)=>'${x['action']}: ${x['effect']}').toList());MarketplaceItem _market(JsonMap j,List<JsonMap> i)=>MarketplaceItem(id:j['id']! as String,name:j['name']! as String,kind:j['kind']! as String,version:j['version']! as String,publisher:j['publisher'] as String? ?? 'ANUM',regions:((j['regions'] as List<Object?>?)??const['global']).cast<String>(),verified:j['verified']! as bool,permissions:((j['permissions'] as List<Object?>?)??const[]).cast<String>(),installed:i.any((x)=>x['package_id']==j['id']));RoutingTarget _target(JsonMap j)=>RoutingTarget(id:j['id']! as String,region:j['region']! as String,provider:j['provider']! as String,model:j['model']! as String,status:j['status']! as String,latencyMs:(j['latency_ms'] as num).toInt(),cost:(j['cost_per_1k_tokens'] as num).toDouble(),modalities:((j['modalities'] as List<Object?>?)??const['text']).cast<String>(),sensitivity:((j['sensitivity'] as List<Object?>?)??const['standard']).cast<String>());EnterpriseOperations _ops(JsonMap j)=>EnterpriseOperations(activeRegions:(j['active_regions'] as num).toInt(),healthyTargets:(j['healthy_targets'] as num).toInt(),degradedTargets:(j['degraded_targets'] as num).toInt(),installedPackages:(j['installed_packages'] as num).toInt(),failoverReady:j['failover_ready']! as bool);}
